package kome.common.data;
import java.util.*;
/** Slice-1 authoritative Neutral/Friends/Allies diplomacy service. */
public final class KOMEDiplomacyService {
 private KOMEDiplomacyService(){}
 public static KOMEDiplomacyRelation getRelation(KOMEWorldData d,String a,String b){String x=KOMEAlliance.normalizeFactionKey(a),y=KOMEAlliance.normalizeFactionKey(b);if(x.length()>0&&x.equals(y))return KOMEDiplomacyRelation.ALLIES;if(d==null||x.length()==0||y.length()==0||x.equals(y))return KOMEDiplomacyRelation.NEUTRAL;KOMEDiplomacyRecord r=d.canonicalDiplomacyRecords.get(KOMEDiplomacyRecord.pairKey(x,y));return r==null?KOMEDiplomacyRelation.NEUTRAL:r.relation;}
 public static boolean isNeutral(KOMEWorldData d,String a,String b){return getRelation(d,a,b)==KOMEDiplomacyRelation.NEUTRAL;}public static boolean areFriends(KOMEWorldData d,String a,String b){return getRelation(d,a,b)==KOMEDiplomacyRelation.FRIENDS;}public static boolean areAllies(KOMEWorldData d,String a,String b){return getRelation(d,a,b)==KOMEDiplomacyRelation.ALLIES;}public static boolean relationAtLeast(KOMEWorldData d,String a,String b,KOMEDiplomacyRelation r){return getRelation(d,a,b).rank()>=r.rank();}
 public static Map<String,KOMEDiplomacyRecord> records(KOMEWorldData d){return Collections.unmodifiableMap(new TreeMap<String,KOMEDiplomacyRecord>(d.canonicalDiplomacyRecords));}
 public static Result requestIncrease(KOMEWorldData d,String from,String to,KOMEDiplomacyRelation target,UUID actor,long now){String a=KOMEAlliance.normalizeFactionKey(from),b=KOMEAlliance.normalizeFactionKey(to);if(d==null||a.length()==0||b.length()==0||a.equals(b)||target==null||target==KOMEDiplomacyRelation.NEUTRAL)return Result.denied("Invalid diplomacy request");if(!d.isFactionKing(a,actor))return Result.denied("Requester must be the recognized King");if(!d.hasFactionKing(b))return Result.denied("Receiving faction has no recognized King");KOMEDiplomacyRecord r=d.canonicalDiplomacyRecords.get(KOMEDiplomacyRecord.pairKey(a,b));KOMEDiplomacyRelation current=r==null?KOMEDiplomacyRelation.NEUTRAL:r.relation;if(target.rank()<=current.rank())return Result.denied("Requested relation must increase current relation");if(r==null){r=new KOMEDiplomacyRecord(a,b);d.canonicalDiplomacyRecords.put(r.key(),r);}if(r.pendingTarget!=null)return Result.denied("A diplomacy request is already pending");r.pendingTarget=target;r.requestingFaction=a;r.receivingFaction=b;r.requesterIdentity=actor==null?"":actor.toString();r.requestedAt=now;d.markDirty();return Result.ok(r);}
 public static Result acceptPendingIncrease(KOMEWorldData d,String receiver,String other,UUID actor,long now){if(d==null)return Result.denied("World data is required");KOMEDiplomacyRecord r=d.canonicalDiplomacyRecords.get(KOMEDiplomacyRecord.pairKey(receiver,other));if(r==null||r.pendingTarget==null)return Result.denied("No pending diplomacy request");String faction=KOMEAlliance.normalizeFactionKey(receiver);if(!faction.equals(r.receivingFaction)||!d.isFactionKing(faction,actor))return Result.denied("Only the receiving faction King may accept");r.relation=r.pendingTarget;r.pendingTarget=null;r.requestingFaction="";r.receivingFaction="";r.requesterIdentity="";r.updatedAt=now;r.lastUpdatedBy=actor==null?"":actor.toString();d.markDirty();return Result.ok(r);}
 public static final class Result{public final boolean accepted;public final String reason;public final KOMEDiplomacyRecord record;private Result(boolean a,String r,KOMEDiplomacyRecord c){accepted=a;reason=r;record=c;}static Result ok(KOMEDiplomacyRecord r){return new Result(true,"",r);}static Result denied(String s){return new Result(false,s,null);}}
}
